CREATE TABLE IF NOT EXISTS public."promotional_video_discussion_likes" (
    "like_id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "comment_id" bigint REFERENCES public."promotional_video_comments" ("comment_id") ON DELETE CASCADE,
    "reply_id" bigint REFERENCES public."promotional_video_replies" ("reply_id") ON DELETE CASCADE,
    "user_id" integer NOT NULL REFERENCES public."users" ("user_id") ON DELETE CASCADE,
    "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (
        ("comment_id" IS NOT NULL AND "reply_id" IS NULL)
        OR ("comment_id" IS NULL AND "reply_id" IS NOT NULL)
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS "promotional_video_discussion_likes_comment_user_key"
    ON public."promotional_video_discussion_likes" ("comment_id", "user_id")
    WHERE "comment_id" IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "promotional_video_discussion_likes_reply_user_key"
    ON public."promotional_video_discussion_likes" ("reply_id", "user_id")
    WHERE "reply_id" IS NOT NULL;

ALTER TABLE public."promotional_video_discussion_likes" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public."promotional_video_discussion_likes" FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public."promotional_video_discussion_likes" TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public."promotional_video_discussion_likes_like_id_seq"
    TO service_role;

CREATE OR REPLACE FUNCTION public.get_promotional_video_discussion()
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $function$
    SELECT jsonb_build_object(
        'video_url', (
            SELECT settings."video_url"
              FROM public."promotional_video_settings" AS settings
             WHERE settings."setting_id" = 1
        ),
        'likes_count', (
            SELECT count(*) FROM public."promotional_video_likes"
        ),
        'comments_count', (
            SELECT count(*) FROM public."promotional_video_comments"
        ),
        'liked_by_me', CASE
            WHEN auth.uid() IS NULL THEN false
            ELSE EXISTS (
                SELECT 1
                  FROM public."promotional_video_likes" AS video_like
                  JOIN public."users" AS account ON account."user_id" = video_like."user_id"
                 WHERE account."auth_user_id" = auth.uid()
                   AND account."is_active" = 1
            )
        END,
        'comments', COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'comment_id', root_comment."comment_id",
                    'full_name', COALESCE(
                        NULLIF(btrim(root_comment."full_name"), ''),
                        root_comment."username",
                        'User'
                    ),
                    'comment', root_comment."comment",
                    'created_at', root_comment."created_at",
                    'is_mine', root_comment."is_mine",
                    'replies_count', root_comment."replies_count",
                    'likes_count', root_comment."likes_count",
                    'liked_by_me', root_comment."liked_by_me",
                    'replies', root_comment."replies"
                )
                ORDER BY root_comment."created_at" DESC, root_comment."comment_id" DESC
            )
              FROM (
                SELECT visible_comment."comment_id",
                       visible_comment."full_name",
                       visible_comment."username",
                       visible_comment."comment",
                       visible_comment."created_at",
                       visible_comment."is_mine",
                       (SELECT count(*)
                          FROM public."promotional_video_replies" AS reply_count
                         WHERE reply_count."comment_id" = visible_comment."comment_id"
                       ) AS "replies_count",
                       (SELECT count(*)
                          FROM public."promotional_video_discussion_likes" AS comment_like
                         WHERE comment_like."comment_id" = visible_comment."comment_id"
                       ) AS "likes_count",
                       EXISTS (
                           SELECT 1
                             FROM public."promotional_video_discussion_likes" AS comment_like
                            WHERE comment_like."comment_id" = visible_comment."comment_id"
                              AND comment_like."user_id" = public.current_app_user_id()
                       ) AS "liked_by_me",
                       COALESCE((
                           SELECT jsonb_agg(
                               jsonb_build_object(
                                   'reply_id', reply_item."reply_id",
                                   'full_name', COALESCE(
                                       NULLIF(btrim(reply_item."full_name"), ''),
                                       reply_item."username",
                                       'User'
                                   ),
                                   'reply', reply_item."reply",
                                   'created_at', reply_item."created_at",
                                   'is_mine', reply_item."is_mine",
                                   'likes_count', reply_item."likes_count",
                                   'liked_by_me', reply_item."liked_by_me"
                               )
                               ORDER BY reply_item."created_at", reply_item."reply_id"
                           )
                             FROM (
                                SELECT video_reply."reply_id",
                                       reply_author."full_name",
                                       reply_author."username",
                                       video_reply."reply",
                                       video_reply."created_at",
                                       auth.uid() IS NOT NULL
                                           AND reply_author."auth_user_id" = auth.uid()
                                           AND reply_author."is_active" = 1 AS "is_mine",
                                       (SELECT count(*)
                                          FROM public."promotional_video_discussion_likes" AS reply_like
                                         WHERE reply_like."reply_id" = video_reply."reply_id"
                                       ) AS "likes_count",
                                       EXISTS (
                                           SELECT 1
                                             FROM public."promotional_video_discussion_likes" AS reply_like
                                            WHERE reply_like."reply_id" = video_reply."reply_id"
                                              AND reply_like."user_id" = public.current_app_user_id()
                                       ) AS "liked_by_me"
                                  FROM (
                                    SELECT video_reply."reply_id",
                                           video_reply."user_id",
                                           video_reply."reply",
                                           video_reply."created_at"
                                      FROM public."promotional_video_replies" AS video_reply
                                     WHERE video_reply."comment_id" = visible_comment."comment_id"
                                     ORDER BY video_reply."created_at" DESC, video_reply."reply_id" DESC
                                     LIMIT 100
                                  ) AS video_reply
                                  JOIN public."users" AS reply_author
                                    ON reply_author."user_id" = video_reply."user_id"
                             ) AS reply_item
                       ), '[]'::jsonb) AS "replies"
                  FROM (
                    SELECT video_comment."comment_id",
                           comment_author."full_name",
                           comment_author."username",
                           video_comment."comment",
                           video_comment."created_at",
                           auth.uid() IS NOT NULL
                               AND comment_author."auth_user_id" = auth.uid()
                               AND comment_author."is_active" = 1 AS "is_mine",
                           row_number() OVER (
                               ORDER BY video_comment."created_at" DESC, video_comment."comment_id" DESC
                           ) AS "list_position"
                      FROM public."promotional_video_comments" AS video_comment
                      JOIN public."users" AS comment_author
                        ON comment_author."user_id" = video_comment."user_id"
                  ) AS visible_comment
                 WHERE visible_comment."list_position" <= 100 OR visible_comment."is_mine"
              ) AS root_comment
        ), '[]'::jsonb)
    );
$function$;

CREATE OR REPLACE FUNCTION public.toggle_promotional_video_discussion_like(
    p_target_type text,
    p_target_id bigint
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
    app_user_id integer;
    like_is_active boolean;
    like_count bigint;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Sign in to like comments and replies.';
    END IF;
    app_user_id := public.current_app_user_id();
    IF app_user_id IS NULL THEN
        RAISE EXCEPTION 'An active account is required to like comments and replies.';
    END IF;
    IF p_target_type IS NULL OR p_target_type NOT IN ('comment', 'reply')
       OR p_target_id IS NULL OR p_target_id <= 0 THEN
        RAISE EXCEPTION 'Choose a valid comment or reply.';
    END IF;

    IF p_target_type = 'comment' THEN
        PERFORM 1
          FROM public."promotional_video_comments"
         WHERE "comment_id" = p_target_id
         FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Comment not found.';
        END IF;

        DELETE FROM public."promotional_video_discussion_likes"
         WHERE "comment_id" = p_target_id
           AND "user_id" = app_user_id;
        like_is_active := NOT FOUND;
        IF like_is_active THEN
            INSERT INTO public."promotional_video_discussion_likes" ("comment_id", "user_id")
            VALUES (p_target_id, app_user_id);
        END IF;
        SELECT count(*)
          INTO like_count
          FROM public."promotional_video_discussion_likes"
         WHERE "comment_id" = p_target_id;
    ELSE
        PERFORM 1
          FROM public."promotional_video_replies"
         WHERE "reply_id" = p_target_id
         FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Reply not found.';
        END IF;

        DELETE FROM public."promotional_video_discussion_likes"
         WHERE "reply_id" = p_target_id
           AND "user_id" = app_user_id;
        like_is_active := NOT FOUND;
        IF like_is_active THEN
            INSERT INTO public."promotional_video_discussion_likes" ("reply_id", "user_id")
            VALUES (p_target_id, app_user_id);
        END IF;
        SELECT count(*)
          INTO like_count
          FROM public."promotional_video_discussion_likes"
         WHERE "reply_id" = p_target_id;
    END IF;

    RETURN jsonb_build_object(
        'type', 'success',
        'active', like_is_active,
        'likes_count', like_count
    );
END;
$function$;

REVOKE ALL ON FUNCTION public.toggle_promotional_video_discussion_like(text, bigint)
    FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.toggle_promotional_video_discussion_like(text, bigint)
    TO authenticated;
